/**
 * Help text for a setting key in a locale: the exact key's text, else the text
 * of the `*` pattern whose other segments match, else undefined.
 */
export function settingHelp(key: string, locale: Locale): string | undefined {
  const texts = SETTING_HELP[locale];
  if (Object.hasOwn(texts, key)) return texts[key];
  const parts = key.split(".");
  for (const [pattern, text] of Object.entries(texts)) {
    if (!pattern.includes("*")) continue;
    const pieces = pattern.split(".");
    if (pieces.length === parts.length && pieces.every((piece, index) => piece === "*" || piece === parts[index])) return text;
  }
  return undefined;
}
